var o=[{title:`Principiante`,text:`Pode ter pouca experiência regular de treino de resistência, estar a regressar após uma longa pausa ou ser novo num movimento. Exercícios simples, prática repetida da técnica, cargas moderadas e algumas boas séries de trabalho adequam-se a esta fase. O progresso rápido inicial vem muitas vezes de melhor coordenação e familiaridade, além de novo tecido muscular.`},{title:`Intermédio`,text:`Faz os principais padrões de forma consistente, consegue estimar o esforço, repete a técnica de sessão para sessão e progride através de alterações planeadas de carga ou repetições. Pode precisar de distribuir o trabalho por vários dias, contar as séries difíceis e prestar mais atenção à recuperação e às estagnações.`},{title:`Avançado`,text:`Avançado significa um longo historial de prática produtiva numa disciplina específica, com um progresso que se tornou lento. Um planeamento mais complexo pode ajudar, embora a complexidade não seja uma conquista em si. Alguém avançado na corrida pode continuar a ser principiante nos agachamentos com barra.`},{title:`Verificações úteis`,text:`Consegue agachar ou fazer a dobradiça da anca numa amplitude controlada? Consegue fazer uma variação de flexão sem perder a posição do corpo? Sabe como se sente uma série com duas repetições de reserva? São observações de treino, não testes universais de passa ou chumba. Nenhum número de flexões, peso no agachamento ou meses de treino classifica corretamente toda a gente.`},{title:`O que significa para o seu programa`,text:`Duas ou três sessões de corpo inteiro baseadas nos padrões de movimento básicos costumam bastar a um iniciante. Um praticante treinado pode precisar de mais volume semanal ou de exercícios mais específicos. Ambos seguem os mesmos princípios: especificidade, progressão gradual e recuperação.`},{title:`Usar o TrainUp`,text:`Defina o seu nível de condição física no Perfil de acordo com o que consegue fazer agora, não com o que espera conseguir. Se está a regressar após uma pausa, comece com cargas mais leves e menos volume. Atualize o nível à medida que a técnica, a consistência e a tolerância melhoram.`}];var s=[{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`CDC: começar em segurança`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var i={sections:o,sources:s};export{i as default,o as sections,s as sources};